package game.dragonboy;

import com.google.gson.*;
import com.sun.net.httpserver.*;
import org.mindrot.jbcrypt.BCrypt;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;

public class Main {
  static final Gson G=new Gson(); static final SecureRandom RNG=new SecureRandom();
  static final String DB=System.getenv().getOrDefault("DB_URL","jdbc:mariadb://127.0.0.1:3306/dragonboy");
  static final String USER=System.getenv().getOrDefault("DB_USER","root"), PASS=System.getenv().getOrDefault("DB_PASS","");
  static final Map<Long,Long> lastAttack=new ConcurrentHashMap<>();
  static Connection db() throws SQLException{return DriverManager.getConnection(DB,USER,PASS);}
  static void send(HttpExchange x,int status,Object data)throws IOException{byte[] b=G.toJson(data).getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");x.getResponseHeaders().set("Access-Control-Allow-Origin","*");x.getResponseHeaders().set("Access-Control-Allow-Headers","Content-Type, Authorization");x.getResponseHeaders().set("Access-Control-Allow-Methods","GET, POST, OPTIONS");if(status==204){x.sendResponseHeaders(status,-1);x.close();return;}x.sendResponseHeaders(status,b.length);x.getResponseBody().write(b);x.close();}
  static JsonObject body(HttpExchange x)throws IOException{return JsonParser.parseString(new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8)).getAsJsonObject();}
  static String str(JsonObject j,String k){return j.has(k)&&!j.get(k).isJsonNull()?j.get(k).getAsString():"";}
  static long num(JsonObject j,String k,long d){try{return j.get(k).getAsLong();}catch(Exception e){return d;}}
  static String token(){byte[] b=new byte[32];RNG.nextBytes(b);return HexFormat.of().formatHex(b);}
  static long auth(HttpExchange x)throws SQLException{String h=x.getRequestHeaders().getFirst("Authorization");if(h==null||!h.startsWith("Bearer "))return 0;try(Connection c=db();PreparedStatement p=c.prepareStatement("SELECT account_id FROM sessions WHERE token=? AND expires_at>NOW()")){p.setString(1,h.substring(7));try(ResultSet r=p.executeQuery()){return r.next()?r.getLong(1):0;}}}
  static Map<String,Object> character(Connection c,long aid)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT id,name,class_id,level,exp,power,hp,max_hp,mp,max_mp,coins,map_id,x,y,kills FROM characters WHERE account_id=?")){p.setLong(1,aid);try(ResultSet r=p.executeQuery()){if(!r.next())return null;Map<String,Object> m=new LinkedHashMap<>();for(String k:List.of("id","name","class_id","level","exp","power","hp","max_hp","mp","max_mp","coins","map_id","x","y","kills"))m.put(k,r.getObject(k));return m;}}}
  static void route(HttpExchange x)throws IOException{try{String path=x.getRequestURI().getPath(),method=x.getRequestMethod();if(method.equals("OPTIONS")){send(x,204,Map.of());return;}if(path.equals("/health")){send(x,200,Map.of("ok",true,"service","DragonBoy API","protocol",2));return;}
    if(method.equals("POST")&&(path.equals("/api/register")||path.equals("/api/login"))){JsonObject j=body(x);String u=str(j,"username").trim(),pw=str(j,"password");if(!u.matches("[A-Za-z0-9_]{3,32}")||pw.length()<8){send(x,400,Map.of("ok",false,"error","invalid_input"));return;}try(Connection c=db()){long aid;
      if(path.endsWith("register")){try(PreparedStatement p=c.prepareStatement("INSERT INTO accounts(username,password_hash) VALUES(?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,u);p.setString(2,BCrypt.hashpw(pw,BCrypt.gensalt(12)));p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();aid=r.getLong(1);}}}else{try(PreparedStatement p=c.prepareStatement("SELECT id,password_hash,status FROM accounts WHERE username=?")){p.setString(1,u);try(ResultSet r=p.executeQuery()){if(!r.next()||!r.getString("status").equals("active")||!BCrypt.checkpw(pw,r.getString("password_hash"))){send(x,401,Map.of("ok",false,"error","login_failed"));return;}aid=r.getLong("id");}}}
      String t=token();try(PreparedStatement p=c.prepareStatement("INSERT INTO sessions(token,account_id,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 DAY))")){p.setString(1,t);p.setLong(2,aid);p.executeUpdate();}send(x,200,Map.of("ok",true,"accountId",aid,"token",t,"protocol",2));}return;}
    long aid=auth(x);if(aid==0){send(x,401,Map.of("ok",false,"error","unauthorized"));return;}
    if(method.equals("POST")&&path.equals("/api/logout")){String h=x.getRequestHeaders().getFirst("Authorization");try(Connection c=db();PreparedStatement p=c.prepareStatement("DELETE FROM sessions WHERE token=?")){p.setString(1,h.substring(7));p.executeUpdate();}send(x,200,Map.of("ok",true));return;}
    if(method.equals("POST")&&path.equals("/api/character/create")){JsonObject j=body(x);String n=str(j,"name").trim();int cls=(int)num(j,"classId",-1);if(!n.matches("[A-Za-z0-9_]{3,16}")||cls<0||cls>2){send(x,400,Map.of("ok",false,"error","invalid_character"));return;}try(Connection c=db();PreparedStatement p=c.prepareStatement("INSERT INTO characters(account_id,name,class_id) VALUES(?,?,?)")){p.setLong(1,aid);p.setString(2,n);p.setInt(3,cls);p.executeUpdate();send(x,200,Map.of("ok",true,"character",character(c,aid)));}return;}
    if(method.equals("GET")&&path.equals("/api/character")){try(Connection c=db()){Map<String,Object> ch=character(c,aid);if(ch==null)send(x,404,Map.of("ok",false,"error","no_character"));else{ch.put("ok",true);send(x,200,ch);}}return;}
    if(method.equals("POST")&&path.equals("/api/game/attack")){long now=System.currentTimeMillis(),prev=lastAttack.getOrDefault(aid,0L);if(now-prev<650){send(x,429,Map.of("ok",false,"error","cooldown"));return;}lastAttack.put(aid,now);try(Connection c=db()){c.setAutoCommit(false);try{Map<String,Object> ch=character(c,aid);if(ch==null){c.rollback();send(x,404,Map.of("ok",false,"error","no_character"));return;}long cid=((Number)ch.get("id")).longValue(),power=((Number)ch.get("power")).longValue();int lvl=((Number)ch.get("level")).intValue();JsonObject req=body(x);boolean skill=req.has("skill")&&req.get("skill").getAsBoolean();long mp=((Number)ch.get("mp")).longValue();if(skill&&mp<10){c.rollback();send(x,400,Map.of("ok",false,"error","not_enough_mp"));return;}int damage=(int)Math.max(8,Math.min(9999,(10+power/10+lvl*3)*(skill?3:1)));if(skill){try(PreparedStatement p=c.prepareStatement("UPDATE characters SET mp=mp-10 WHERE id=?")){p.setLong(1,cid);p.executeUpdate();}}try(PreparedStatement p=c.prepareStatement("INSERT IGNORE INTO character_battle(character_id,enemy_hp,enemy_max_hp) VALUES(?,100,100)")){p.setLong(1,cid);p.executeUpdate();}int enemyHp;try(PreparedStatement p=c.prepareStatement("SELECT enemy_hp FROM character_battle WHERE character_id=? FOR UPDATE")){p.setLong(1,cid);try(ResultSet r=p.executeQuery()){r.next();enemyHp=r.getInt(1);}}enemyHp=Math.max(0,enemyHp-damage);boolean defeated=enemyHp==0;if(defeated)enemyHp=100;try(PreparedStatement p=c.prepareStatement("UPDATE character_battle SET enemy_hp=? WHERE character_id=?")){p.setInt(1,enemyHp);p.setLong(2,cid);p.executeUpdate();}if(defeated){long exp=20L+lvl*5;try(PreparedStatement p=c.prepareStatement("UPDATE characters SET exp=exp+?,kills=kills+1,coins=coins+5 WHERE id=?")){p.setLong(1,exp);p.setLong(2,cid);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE characters SET level=level+1,max_hp=max_hp+10,hp=max_hp+10,max_mp=max_mp+5,mp=max_mp+5,power=power+2,exp=exp-(level*100) WHERE id=? AND exp>=level*100")){p.setLong(1,cid);p.executeUpdate();}}c.commit();Map<String,Object> out=character(c,aid);out.put("ok",true);out.put("damage",damage);out.put("enemyHp",enemyHp);out.put("defeated",defeated);send(x,200,out);}catch(Exception e){c.rollback();throw e;}}return;}
    if(method.equals("POST")&&path.equals("/api/game/heal")){try(Connection c=db();PreparedStatement p=c.prepareStatement("UPDATE characters SET hp=max_hp,mp=max_mp WHERE account_id=?")){p.setLong(1,aid);p.executeUpdate();try(Connection c2=db()){Map<String,Object> out=character(c2,aid);out.put("ok",true);send(x,200,out);}}return;}
    send(x,404,Map.of("ok",false,"error","not_found"));
  }catch(SQLIntegrityConstraintViolationException e){send(x,409,Map.of("ok",false,"error","name_or_account_exists"));}catch(Exception e){e.printStackTrace();send(x,500,Map.of("ok",false,"error","server_error"));}}
  public static void main(String[] a)throws Exception{int port=Integer.parseInt(System.getenv().getOrDefault("PORT","8080"));HttpServer s=HttpServer.create(new InetSocketAddress("0.0.0.0",port),0);s.createContext("/",Main::route);s.setExecutor(Executors.newFixedThreadPool(12));System.out.println("DragonBoy API v2 listening on "+port);s.start();}
}
